/// <summary>
/// Class entry point. The system will call this method when a designated menu 
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    OMGOutboundMessage outboundMessage = new OMGOutboundMessage();

    outboundMessage.parmMessageTypeId('out');
    outboundMessage.parmMessageName('test');
    outboundMessage.parmMessage('{ "name": "jesper", "email" : "jdy@obtain.dk" }');

    outboundMessage.parmMetadata().add('name', 'jesper');
    outboundMessage.parmMetadata().add('email', 'jdy@obtain.dk');

    outboundMessage.send();
}
